// Extrai menor preço encontrado no Zoom (regex simples do HTML)
// Zoom mostra preços em <span class="...">R$ X.XXX,XX</span>
const html = String($input.item.json.data || $input.item.json);
const precos = [...html.matchAll(/R\$\s*([\d.]+,\d{2})/g)]
  .map(m => parseFloat(m[1].replace(/\./g, '').replace(',', '.')))
  .filter(p => p > 10 && p < 100000);

const menorZoom = precos.length ? Math.min(...precos) : null;
const mediaZoom = precos.length ? precos.reduce((a,b) => a+b, 0) / precos.length : null;

const oferta = $('Ofertas recentes não validadas').item.json;
const precoOferta = parseFloat(oferta.preco);

let veredicto = 'sem_dados';
let score = 0;

if (menorZoom) {
  if (precoOferta <= menorZoom * 0.95) {
    veredicto = 'oferta_real';
    score = 100;
  } else if (precoOferta <= menorZoom * 1.10) {
    veredicto = 'preco_medio';
    score = 50;
  } else {
    veredicto = 'sem_desconto';
    score = 10;
  }
}

return {
  json: {
    id: oferta.id,
    preco_oferta: precoOferta,
    menor_zoom: menorZoom,
    media_zoom: mediaZoom,
    veredicto,
    score_confianca: score
  }
};
